int? ParseOptionalScore(string cell)
{
    if (string.IsNullOrWhiteSpace(cell))
        return null;
    return int.Parse(cell, CultureInfo.InvariantCulture);
}

int displayed = ParseOptionalScore(row["score"]) ?? 0;

